**PROBE — what a never-designed goal really reads.** Written to `apps/daemon/src/http/zz-probe-deb4c7d8.test.ts`, run, deleted. Result written to a temp file because vitest swallowed `console.log` under this config:
```ts
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { SqliteEventStore } from "@moe/store";
import { describe, expect, it } from "vitest";
import { readDesignRevision } from "../design/design-store.js";

describe("probe", () => {
  it("what does a never-designed goal read as", () => {
    const dir = mkdtempSync(join(tmpdir(), "probe-deb4c7d8-"));
    const store = SqliteEventStore.openForProject(join(dir, "e.db"), "proj-probe");
    let raw: unknown;
    try { raw = store.readEvents("design:goal-never"); }
    catch (error) { raw = `THREW ${String(error)}`; }
    const read = readDesignRevision(store, { goalRef: "goal-never", projectId: "proj-probe" });
    writeFileSync(join(tmpdir(), "probe-deb4c7d8.json"), JSON.stringify({ raw, read }, null, 2));
    store.close(); rmSync(dir, { force: true, recursive: true });
    expect(true).toBe(true);
  });
});
```
Command: `npx vitest run --root . --config apps/daemon/package.json apps/daemon/src/http/zz-probe-deb4c7d8.test.ts` -> `Test Files 1 passed (1) / Tests 1 passed (1)`. Output:
```json
{ "raw": [],
  "read": { "code": "DESIGN_REVISION_ABSENT", "layer": "LEDGER", "ok": false,
            "sourceCode": null, "sourceLayer": null } }
```
`raw: []` is the whole finding: **`readEvents` on an aggregate that never existed returns an EMPTY ARRAY, it does not throw.** `storeFailure` is never reached, so `DESIGN_STORE_UNAVAILABLE` — the plan's strong candidate and the description's headline — is not what a never-designed goal produces. `design-store.ts:204` fires and the shipped mapping at `affordance-read.ts:358` handles it correctly.

